values
    ('148b05f1-f082-faec-1a72-6333678d3011', 'Ogilvie Syndrome', null, array['Acute Colonic Pseudo-obstruction']::text[], array['Hospitalized patient with massive colonic distension', 'No mechanical obstruction', 'Associated with surgery, medications, or critical illness', 'Cecal diameter >12 cm risks perforation', 'Treated with neostigmine or decompression']::text[], 'Gastroenterology', 3, 250),
    ('6db0480f-8f3c-40e9-5e66-15b8879054ad', 'Tropical Sprue', null, '{}'::text[], array['Traveler with chronic diarrhea and malabsorption', 'Folate and B12 deficiency', 'Villous atrophy similar to celiac disease', 'Endemic in Caribbean, India, Southeast Asia', 'Responds to antibiotics and folate']::text[], 'Gastroenterology', 4, 251),
    ('b787a891-c73b-84d7-c9f7-1aa3a7d4722c', 'Ischemic Colitis', null, '{}'::text[], array['Elderly patient with sudden onset bloody diarrhea and abdominal pain', 'Watershed areas most vulnerable (splenic flexure)', 'Thumbprinting on abdominal X-ray', 'Colonoscopy shows segmental inflammation', 'Usually self-limited']::text[], 'Gastroenterology', 3, 252),
    ('db0c89ce-6eed-b214-4baa-c4819cf10f4a', 'Carcinoid Tumor', null, array['Neuroendocrine Tumor']::text[], array['Patient with intermittent diarrhea and facial flushing', 'Most commonly in appendix or small bowel', 'Elevated 5-HIAA in urine', 'Carcinoid syndrome if liver metastases present', 'Treated with octreotide']::text[], 'Gastroenterology', 3, 253),
    ('eb37ff40-20bd-555c-b6b7-505a981bf29b', 'Mesenteric Ischemia', null, array['Acute Mesenteric Ischemia']::text[], array['Elderly patient with severe periumbilical pain out of proportion to exam', 'Pain after eating (intestinal angina) if chronic', 'Atrial fibrillation is risk factor for embolic type', 'Elevated lactate and metabolic acidosis', 'Requires urgent revascularization']::text[], 'Gastroenterology', 3, 254),
    ('9947a4cd-3387-f257-c9e4-4ae7edfba8ed', 'Rapidly Progressive Glomerulonephritis', null, array['RPGN', 'Crescentic GN']::text[], array['Patient with acute kidney injury over days to weeks', 'Hematuria and RBC casts', 'Crescents on kidney biopsy', 'Types: anti-GBM, immune complex, pauci-immune (ANCA)', 'Requires urgent treatment to prevent ESRD']::text[], 'Nephrology', 4, 255),
    ('6086ce12-af59-3a37-775e-3753d3ecfdb9', 'Diabetic Nephropathy', null, array['Diabetic Kidney Disease']::text[], array['Diabetic patient with progressive proteinuria', 'Microalbuminuria is earliest sign', 'Kimmelstiel-Wilson nodules on biopsy', 'Leading cause of ESRD in United States', 'ACE inhibitors slow progression']::text[], 'Nephrology', 2, 256),
