    ('16076060-f01f-58a4-4f21-207ed56d220e', 'ACE Inhibitor Side Effects', null, '{}'::text[], array['Patient on lisinopril with dry cough', 'Can cause angioedema (contraindicated in pregnancy)', 'Hyperkalemia risk', 'Increased bradykinin causes cough', 'Switch to ARB if cough intolerable']::text[], 'Pharmacology', 2, 460),
