    ('a56d89ef-ba30-199c-0fef-23877682267b', 'Digoxin Toxicity', null, '{}'::text[], array['Elderly patient with nausea and yellow vision', 'Increased automaticity and AV block', 'Bidirectional ventricular tachycardia classic', 'Narrow therapeutic window', 'Treated with digoxin-specific antibody fragments']::text[], 'Pharmacology', 2, 462),
    ('72090e99-f7d9-a7e8-21e6-1e68e3d7b7fe', 'Lithium Toxicity', null, '{}'::text[], array['Bipolar patient with tremor, confusion, and seizures', 'Nephrogenic diabetes insipidus', 'Hypothyroidism with chronic use', 'Narrow therapeutic window (0.6-1.2 mEq/L)', 'Treated with hemodialysis if severe']::text[], 'Pharmacology', 2, 463),
    ('ecf95b6d-55ac-c85e-8e2c-895b0e736081', 'Phenytoin Side Effects', null, array['Dilantin']::text[], array['Epileptic patient with gingival hyperplasia', 'Hirsutism and coarse facial features', 'Megaloblastic anemia (inhibits folate absorption)', 'Teratogenic (fetal hydantoin syndrome)', 'CYP450 inducer']::text[], 'Pharmacology', 2, 464),
    ('c429aa97-6a65-4f92-432d-bbee2382f40b', 'Methotrexate Toxicity', null, '{}'::text[], array['Cancer patient with mucositis and pancytopenia', 'Inhibits dihydrofolate reductase', 'Hepatotoxicity and pulmonary fibrosis', 'Teratogenic', 'Leucovorin (folinic acid) rescue']::text[], 'Pharmacology', 2, 465),
    ('c91f468f-7f62-63c0-d216-63388afa69d4', 'Aminoglycoside Toxicity', null, array['Gentamicin', 'Tobramycin']::text[], array['Patient with hearing loss and acute kidney injury', 'Ototoxicity (vestibular and cochlear)', 'Nephrotoxicity (dose-dependent)', 'Monitor trough levels', 'Can cause neuromuscular blockade']::text[], 'Pharmacology', 2, 466),
    ('4c7edfda-b6d4-00bb-8517-4431bb7e6468', 'Vancomycin Red Man Syndrome', null, '{}'::text[], array['Patient with flushing and pruritus during IV infusion', 'Non-IgE mediated histamine release', 'Not true allergic reaction', 'Prevented by slow infusion rate', 'Can also cause nephrotoxicity and ototoxicity']::text[], 'Pharmacology', 2, 467),
    ('3cd9282d-83f0-2349-d7ce-5bec0adcf968', 'Rifampin Side Effects', null, '{}'::text[], array['TB patient with orange-red discoloration of secretions', 'Potent CYP450 inducer (many drug interactions)', 'Decreases effectiveness of oral contraceptives', 'Hepatotoxicity', 'Colors tears, urine, sweat orange']::text[], 'Pharmacology', 2, 468),
    ('95af3a46-c93a-a41b-6a6b-c453535dcf47', 'Fluoroquinolone Side Effects', null, array['Ciprofloxacin', 'Levofloxacin']::text[], array['Patient with Achilles tendon pain after antibiotic', 'Tendon rupture risk (especially in elderly and steroid users)', 'Can prolong QT interval', 'Contraindicated in pregnancy and children', 'Can cause C. difficile colitis']::text[], 'Pharmacology', 2, 469),
