    ('53673db7-d7b7-896f-3272-43c8fabf4524', 'Amphotericin B Toxicity', null, array['Ampho-terrible']::text[], array['Patient with rigors and fever during infusion', 'Nephrotoxicity and hypokalemia/hypomagnesemia', 'Premedicate with acetaminophen and diphenhydramine', 'Liposomal formulation less toxic', 'Monitor renal function and electrolytes']::text[], 'Pharmacology', 2, 471),
    ('cfab0cef-fcc5-38e4-fac0-4ed9d4c7c0b8', 'Bleomycin Pulmonary Toxicity', null, '{}'::text[], array['Cancer patient with progressive dyspnea', 'Pulmonary fibrosis on imaging', 'Dose-dependent toxicity', 'Monitor with pulmonary function tests', 'Avoid supplemental oxygen if possible']::text[], 'Pharmacology', 3, 472),
