    ('87368c97-83e9-bbe1-4049-9ae28267a614', 'Vincristine Neurotoxicity', null, '{}'::text[], array['Leukemia patient with peripheral neuropathy', 'Foot drop and loss of reflexes', 'Inhibits microtubule polymerization', 'Constipation common (autonomic neuropathy)', 'Dose-limiting toxicity']::text[], 'Pharmacology', 3, 474),
