    ('06a46444-5931-6d63-60ad-a25266d485ed', 'Cyclophosphamide Toxicity', null, '{}'::text[], array['Patient with hemorrhagic cystitis', 'Acrolein metabolite damages bladder', 'Prevented with mesna and hydration', 'Myelosuppression and SIADH', 'Increased risk of bladder cancer']::text[], 'Pharmacology', 3, 476),
    ('6ca0d4ec-5cfb-6811-8d68-138c27746944', 'Alcohol Withdrawal', null, array['Delirium Tremens']::text[], array['Hospitalized alcoholic with tremor and hallucinations', 'Autonomic hyperactivity: tachycardia, hypertension, diaphoresis', 'Seizures possible within 48 hours', 'Delirium tremens (DTs) at 48-96 hours', 'Treated with benzodiazepines (CIWA protocol)']::text[], 'Psychiatry', 2, 477),
