    ('5fc5da56-5051-5e94-2235-6a4eac1784ff', 'Attention-Deficit Hyperactivity Disorder', null, array['ADHD', 'Attention Deficit Hyperactivity Disorder']::text[], array['Child with inattention and hyperactivity', 'Difficulty completing tasks and sitting still', 'Symptoms present before age 12', 'Impairs academic and social functioning', 'Treated with stimulants (methylphenidate, amphetamines)']::text[], 'Psychiatry', 2, 479),
    ('1c360995-4fb5-f73c-b6ed-313861bcd4a3', 'Autism Spectrum Disorder', null, array['ASD']::text[], array['Child with impaired social communication', 'Repetitive behaviors and restricted interests', 'Symptoms present in early development', 'Variable intellectual functioning', 'Behavioral therapy is mainstay of treatment']::text[], 'Psychiatry', 2, 480),
    ('d531f7f3-023c-5a4e-1b9c-53dd4d9cbe9d', 'Neuroleptic Malignant Syndrome', null, array['NMS']::text[], array['Patient on antipsychotic with fever and rigidity', 'Lead-pipe rigidity and altered mental status', 'Elevated CK and myoglobinuria', 'Autonomic instability', 'Treated with dantrolene and bromocriptine']::text[], 'Psychiatry', 3, 481),
    ('e36428d1-f016-6d26-e338-620a630ad4a1', 'Serotonin Syndrome', null, '{}'::text[], array['Patient on SSRIs with agitation and hyperthermia', 'Hyperreflexia and clonus', 'Tremor and diaphoresis', 'Mydriasis and flushing', 'Treated with cyproheptadine and supportive care']::text[], 'Psychiatry', 3, 482),
    ('5f9f0fe5-cb3f-2440-3556-b47f77a9fd13', 'Deep Vein Thrombosis', null, array['DVT']::text[], array['Patient with unilateral leg swelling and pain', 'Positive Homan sign (calf pain with dorsiflexion)', 'Risk factors: immobility, surgery, malignancy, hypercoagulable state', 'Duplex ultrasound for diagnosis', 'Treated with anticoagulation']::text[], 'Vascular', 2, 483),
    ('51b4c0a4-4937-b7b6-c70a-a798db1d1b60', 'Peripheral Arterial Disease', null, array['PAD']::text[], array['Patient with claudication (calf pain with walking)', 'Decreased or absent pulses', 'Low ankle-brachial index (<0.9)', 'Hair loss and shiny skin on legs', 'Risk factors: smoking, diabetes, hyperlipidemia']::text[], 'Vascular', 2, 484),
    ('db3d3f69-b548-be25-201f-25486d6b034f', 'Abdominal Aortic Aneurysm', null, array['AAA']::text[], array['Elderly male with pulsatile abdominal mass', 'Often asymptomatic until rupture', 'Rupture triad: hypotension, back pain, pulsatile mass', 'Screen men 65-75 who have smoked', 'Repair if >5.5 cm or symptomatic']::text[], 'Vascular', 2, 485),
    ('523328c3-f993-b8cd-b318-a548fcafa022', 'Varicose Veins', null, '{}'::text[], array['Patient with dilated, tortuous superficial veins', 'Leg pain and heaviness worse at end of day', 'Risk factors: pregnancy, prolonged standing, obesity', 'Incompetent venous valves', 'Can lead to venous stasis ulcers']::text[], 'Vascular', 2, 486),
    ('0e9d3fee-5470-3201-feec-014c05550042', 'Hypovolemic Shock', null, '{}'::text[], array['Patient with hypotension and tachycardia after trauma', 'Cold, clammy skin', 'Decreased urine output', 'Narrow pulse pressure', 'Treated with fluid resuscitation']::text[], 'Critical Care', 2, 487),
    ('3637a49a-354b-d488-29ca-0dea9f7f82ab', 'Cardiogenic Shock', null, '{}'::text[], array['Patient with hypotension and pulmonary edema after MI', 'Elevated JVP and S3 gallop', 'Decreased cardiac output', 'Cool extremities', 'Requires inotropic support']::text[], 'Critical Care', 2, 488),
    ('407010e9-82fa-12e6-7e73-e1dbbf1d0f23', 'Septic Shock', null, array['Distributive Shock']::text[], array['Febrile patient with hypotension refractory to fluids', 'Warm extremities initially (high cardiac output)', 'Elevated lactate', 'Requires vasopressors (norepinephrine)', 'Source control and broad-spectrum antibiotics']::text[], 'Critical Care', 2, 489),
    ('45380246-a028-096b-35cb-4048eacecc0b', 'Obstructive Shock', null, '{}'::text[], array['Patient with hypotension and elevated JVP', 'Causes: tension pneumothorax, PE, tamponade', 'Muffled heart sounds if tamponade', 'Decreased cardiac output from obstruction', 'Requires relief of obstruction']::text[], 'Critical Care', 2, 490),
    ('22458f0f-be21-2826-c999-1f219b18047a', 'Patent Foramen Ovale', null, array['PFO']::text[], array['Young patient with stroke without risk factors', 'Paradoxical embolism through atrial defect', 'Present in 25% of population', 'Usually asymptomatic', 'Bubble study on echocardiogram']::text[], 'Cardiology', 2, 491),
    ('493575f4-d092-d786-4f48-5d1b575b3aec', 'Meckel Diverticulum', null, '{}'::text[], array['Child with painless rectal bleeding', 'Rule of 2''s: 2 feet from ileocecal valve, 2 inches long, 2% population', 'Contains ectopic gastric mucosa', 'Technetium-99m scan (Meckel scan)', 'Most common congenital GI anomaly']::text[], 'Gastroenterology', 2, 492),
    ('9b9d5fa9-b2e4-6560-98fe-61c698f997ab', 'Omphalocele', null, '{}'::text[], array['Newborn with abdominal contents in sac at umbilicus', 'Covered by peritoneum and amnion', 'Associated with chromosomal abnormalities', 'Liver may be in sac', 'Better prognosis than gastroschisis']::text[], 'Pediatrics', 2, 493),
    ('f587ee9b-e54d-65c5-52f5-130cdea4345e', 'Gastroschisis', null, '{}'::text[], array['Newborn with intestines protruding through abdominal wall', 'No covering membrane', 'Lateral to umbilicus (usually right)', 'Not associated with chromosomal abnormalities', 'Requires surgical repair']::text[], 'Pediatrics', 2, 494),
    ('78bc3f1a-6b36-8158-592e-a0bf02585f75', 'Duodenal Atresia', null, '{}'::text[], array['Newborn with bilious vomiting', 'Double bubble sign on X-ray', 'Associated with Down syndrome', 'Polyhydramnios during pregnancy', 'Requires surgical correction']::text[], 'Pediatrics', 2, 495),
    ('efe47354-9a00-1582-a815-a28282bc0ae5', 'Biliary Atresia', null, '{}'::text[], array['Infant with prolonged jaundice and acholic stools', 'Progressive cholestatic jaundice after 2 weeks', 'Direct hyperbilirubinemia', 'Leads to cirrhosis if untreated', 'Kasai procedure (hepatoportoenterostomy)']::text[], 'Pediatrics', 3, 496),
    ('e5eeda91-3ef7-8fcb-6874-2ae01de26426', 'Pseudomembranous Colitis', null, array['C. diff Colitis', 'Clostridioides difficile']::text[], array['60-year-old female with profuse watery diarrhea and cramping', 'History of recent Clindamycin use for a skin infection', 'Leukocytosis and fever present', 'Yellowish-white plaques on colonic mucosa during colonoscopy', 'Toxins A and B detected in the stool']::text[], 'Infectious Disease / GI', 2, 497),
    ('671becb9-13a1-a42f-26e3-b982387fccda', 'Pneumocystis Jirovecii Pneumonia', null, array['PCP', 'Pneumocystosis']::text[], array['35-year-old male with HIV and a CD4 count of 150', 'Progressive exertional dyspnea and non-productive cough', 'Bilateral ''ground-glass'' opacities on chest X-ray', 'Silver stain (GMS) of induced sputum shows disc-shaped cysts', 'Prophylaxis and treatment with Trimethoprim-Sulfamethoxazole']::text[], 'Infectious Disease', 2, 498),
    ('4b7daa7f-50f8-e0c6-bbf4-4261390bca37', 'Ewing Sarcoma', null, array['Small Blue Round Cell Tumor']::text[], array['12-year-old boy with localized pain and swelling in the femur', 'Fever, leukocytosis, and an elevated ESR', 'X-ray shows a ''moth-eaten'' appearance and ''onion-skin'' periosteal reaction', 'Biopsy reveals small, round, blue cells', 't(11;22) translocation involving the EWS-FLI1 gene']::text[], 'Orthopedics / Oncology', 4, 499)
