values
    ('915878c6-efec-b360-da18-623012a05d1b', 'Pernicious Anemia', null, array['Vitamin B12 Deficiency', 'Megaloblastic Anemia']::text[], array['60-year-old female with tingling in her feet and a smooth, sore tongue', 'Increased mean corpuscular volume (MCV > 100 fL)', 'Hypersegmented neutrophils on peripheral blood smear', 'Degeneration of the dorsal columns of the spinal cord', 'Anti-intrinsic factor or anti-parietal cell antibodies']::text[], 'Hematology', 3, 500),
    ('1e644fdc-1e9d-23ba-0f2e-392c51717367', 'Osteosarcoma', null, array['Osteogenic Sarcoma']::text[], array['16-year-old male with knee pain that wakes him at night', 'Swelling above the knee; no systemic fever', 'Codman triangle (periosteal elevation) on X-ray', '''Sunburst'' pattern of bone spicules', 'Associated with mutations in RB1 and TP53 genes']::text[], 'Orthopedics / Oncology', 3, 501),
    ('39f7bfef-2c48-1aa2-95cc-84db14154a33', 'Granulomatosis with Polyangiitis', 'granulomatosis-with-polyangiitis', array['Wegener Granulomatosis', 'GPA']::text[], array['50-year-old male with chronic sinusitis and bloody sputum', 'Hematuria and saddle-nose deformity', 'C-ANCA (PR3-ANCA) positivity', 'Necrotizing granulomas in upper/lower respiratory tracts', 'Triad: Focal necrotizing vasculitis, lung granulomas, glomerulonephritis']::text[], 'Rheumatology / Vasculitis', 4, 502),
    ('f9979ecd-a50e-1f80-4e73-5322f79b2a33', 'Diabetes Insipidus (Central)', 'diabetes-insipidus', array['Neurogenic DI']::text[], array['30-year-old following head trauma with intense thirst', 'Massive volumes of dilute urine (low specific gravity)', 'Serum hyperosmolality; urine hypoosmolality', 'Water deprivation test shows increase in urine osmolality after Desmopressin', 'ADH deficiency from the posterior pituitary']::text[], 'Endocrinology', 3, 503),
    ('8df74102-bc55-72e9-2dbb-94d152960494', 'Glioblastoma Multiforme', null, array['GBM', 'Grade IV Astrocytoma']::text[], array['60-year-old with personality changes and new headaches', 'Ring-enhancing lesion on MRI crossing the corpus callosum', '''Butterfly glioma'' appearance', 'Histology: Pseudopalisading necrosis and hemorrhage', 'Most common malignant primary brain tumor in adults']::text[], 'Neurology / Oncology', 3, 504),
    ('73b64515-2501-fb0b-672b-4ddf61a697ca', 'Paget Disease of Bone', null, array['Osteitis Deformans']::text[], array['70-year-old male noticing his hat size has increased', 'Hearing loss and deep bone pain', 'Isolated elevation of Alkaline Phosphatase (ALP)', '''Mosaic'' pattern of lamellar bone (bone remodeling)', 'Increased risk of high-output heart failure and osteosarcoma']::text[], 'Rheumatology / Orthopedics', 4, 505),
    ('3e1e3ee4-4e0f-4aa5-1d1f-06c6dc00a096', 'Burkitt Lymphoma', null, array['B-cell Non-Hodgkin Lymphoma']::text[], array['8-year-old African boy with a rapidly growing jaw mass', 'EBV association (endemic form)', 'Histology: ''Starry sky'' appearance (tingible body macrophages)', 'High mitotic index and Ki-67 staining', 't(8;14) translocation of the c-myc gene']::text[], 'Hematology / Oncology', 3, 506),
    ('780b0e47-c7d6-ffec-4ff3-bf81ed8680bb', 'Scleroderma (Diffuse)', 'systemic-sclerosis', array['Systemic Sclerosis']::text[], array['45-year-old female with stiff, tight skin on the chest and arms', 'Raynaud phenomenon and heartburn (GERD)', 'Pulmonary fibrosis or renal crisis', 'Anti-Scl-70 (anti-DNA topoisomerase I) antibodies', 'Widespread collagen deposition in skin and internal organs']::text[], 'Rheumatology', 3, 507),
    ('05ffcb00-01fc-4d12-b13c-f9ff4e4c29d1', 'Gardner Syndrome', null, array['FAP with Extra-intestinal Manifestations']::text[], array['20-year-old with hundreds of polyps on colonoscopy', 'Multiple osteomas of the jaw and skull', 'Hypertrophy of retinal pigment epithelium (CHRPE)', 'Desmoid tumors and impacted teeth', 'Autosomal dominant mutation of the APC gene']::text[], 'Gastroenterology / Genetics', 4, 508),
    ('07ceb1f0-d698-630a-8f4b-74d560bf5edc', 'Primary Hyperparathyroidism', null, array['Parathyroid Adenoma']::text[], array['50-year-old with ''stones, bones, groans, and psychic overtones''', 'Hypercalcemia, hypophosphatemia, and elevated ALP', 'Subperiosteal bone resorption and brown tumors (osteitis fibrosa cystica)', 'Increased urinary cAMP', 'Usually caused by a single parathyroid adenoma']::text[], 'Endocrinology', 4, 509),
    ('10bd562d-befd-d23e-5597-5c6be68b6ffb', 'Polycystic Kidney Disease (ADPKD)', 'polycystic-kidney-disease', array['Adult PKD']::text[], array['40-year-old with flank pain, hematuria, and hypertension', 'Bilateral palpable flank masses', 'Associated with berry aneurysms and liver cysts', 'Mutation in PKD1 (chromosome 16) or PKD2 (chromosome 4)', 'Progressive renal failure by age 50']::text[], 'Nephrology / Genetics', 3, 510),
    ('16494d89-3082-0d95-90de-12bbbfb9593f', 'Von Hippel-Lindau Disease', null, array['VHL', 'Von Hippel Lindau Disease']::text[], array['Patient with hemangioblastomas in the cerebellum and retina', 'Bilateral renal cell carcinomas (clear cell)', 'Pheochromocytomas', 'Deletion of VHL gene on chromosome 3', 'VHL protein normally targets HIF-1a for degradation']::text[], 'Genetics / Oncology', 4, 511),
    ('6a1b1cf6-877a-18fc-9a67-3f949df770fa', 'Sjögren Syndrome', 'sjogren-syndrome', array['Sicca Syndrome']::text[], array['Woman with dry eyes (xerophthalmia) and dry mouth (xerostomia)', 'Dental caries and bilateral parotid gland enlargement', 'Anti-Ro (SS-A) and Anti-La (SS-B) antibodies', 'Lymphocytic infiltration of exocrine glands', 'Increased risk of B-cell (MALT) lymphoma']::text[], 'Rheumatology', 3, 512),
    ('fb09a6ec-5560-09a8-bc7e-c3570b09c037', 'Botulism', null, '{}'::text[], array['Adult with diplopia, dysphagia, and descending paralysis', 'History of improperly canned food', 'Toxin prevents ACh release at neuromuscular junction', 'Floppy baby syndrome in infants from honey', 'Treat with antitoxin']::text[], 'Infectious Disease', 4, 513)
